/bin/bash -lc "python - <<'PY'
import numpy as np
from collections import Counter
from scipy.ndimage import label
f=np.load('source_pixels.npz')['rgb']
for t in [0,10,20,40,60,95]:
 a=f[t]; print('\\nFRAME',t,'palette',Counter(map(tuple,a.reshape(-1,3))).most_common(12))
 masks={'purple':(a[:,:,2].astype(int)>a[:,:,1]+25)&(a[:,:,0].astype(int)>a[:,:,1]+20), 'red':(a[:,:,0].astype(int)>a[:,:,1]+40)&(a[:,:,0].astype(int)>a[:,:,2]+20),'green':(a[:,:,1].astype(int)>a[:,:,0]+20)&(a[:,:,1].astype(int)>a[:,:,2]+10), 'blue':(a[:,:,2].astype(int)>a[:,:,0]+30)&(a[:,:,2].astype(int)>a[:,:,1]+10)}
 for n,m in masks.items():
  lab,num=label(m); out=[]
  for i in range(1,num+1):
   ys,xs=np.where(lab==i)
   if len(xs)>4: out.append((len(xs),[xs.min(),ys.min(),xs.max(),ys.max()],[xs.mean().round(2),ys.mean().round(2)]))
  print(n,out)
# ascii map of mean RGB 4x4 pixels, manual color letters
for t in [0,30,60,95]:
 a=f[t].astype(float).reshape(36,4,64,4,3).mean((1,3)); print('\\nMAP',t)
 for row in a:
  line=''
  for r,g,b in row:
   if max(r,g,b)-min(r,g,b)<12: c=' ' if r>180 else ('.' if r>70 else '#')
   elif b>g+20 and r>g+15:c='P'
   elif b>r+20:c='B'
   elif r>g+35 and r>b+20:c='R'
   elif g>r+20:c='G'
   elif r>110 and g>80 and b<80:c='Y'
   else:c=':'
   line+=c
  print(line)
PY"
